/// <summary>
/// Handles the logic of priniting the report
/// </summary>
/// <param name = "_args">controller args</param>
static void main(Args _args)
{
    METSalesOrderShipmentBundlingReportController controller;

    controller = new METSalesOrderShipmentBundlingReportController();
    controller.parmReportName(ssrsReportStr(Report1, BundlingReport));
    controller.parmDialogCaption("Sales order Bundling report");
    controller.parmArgs(_args);

    METSalesOrderShipmentBundlingReportContract contract = controller.parmReportContract().parmRdpContract();

    controller.startOperation();
}
